def f(w):
    return (w - 3) ** 2

print(f(1), f(3), f(5))   # 4 0 4

def grad(w):
    return 2 * (w - 3)

for start in [0.4, 5.6]:
    w = start
    for _ in range(30):
        w = w - 0.3 * grad(w)
    print(start, round(w, 3))   # 0.4 3.0 / 5.6 3.0

def g(w):
    return (w ** 2 - 1) ** 2 + 0.3 * w

def g_grad(w):
    return 4 * w * (w ** 2 - 1) + 0.3

print(g(0.0), 0.5 * g(-1.0) + 0.5 * g(1.0))   # 1.0 0.0 : above the chord
for start in [-2.0, 2.0]:
    w = start
    for _ in range(200):
        w = w - 0.02 * g_grad(w)
    print(start, round(w, 2), round(g(w), 2))
# -2.0 -1.04 -0.31
# 2.0 0.96 0.29
